// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.OfflinePayment.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(offlinepayment.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *OfflinePaymentUpsertBulk) UpdateNewValues() *OfflinePaymentUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(offlinepayment.FieldID)
			}
			if _, exists := b.mutation.Namespace(); exists {
				s.SetIgnore(offlinepayment.FieldNamespace)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(offlinepayment.FieldCreatedAt)
			}
			if _, exists := b.mutation.ReceivableAccountID(); exists {
				s.SetIgnore(offlinepayment.FieldReceivableAccountID)
			}
			if _, exists := b.mutation.AmountCents(); exists {
				s.SetIgnore(offlinepayment.FieldAmountCents)
			}
			if _, exists := b.mutation.Currency(); exists {
				s.SetIgnore(offlinepayment.FieldCurrency)
			}
			if _, exists := b.mutation.ConfirmedBy(); exists {
				s.SetIgnore(offlinepayment.FieldConfirmedBy)
			}
			if _, exists := b.mutation.ConfirmedAt(); exists {
				s.SetIgnore(offlinepayment.FieldConfirmedAt)
			}
		}
	}))
	return u
}

